+				coverage_set_output(E->next()->get());
+			} else if (arg == "--coverage-mode" && E->next()) {
+				coverage_set_mode(E->next()->get());
+			} else if (arg == "--coverage-format" && E->next()) {
+				coverage_set_format(E->next()->get());
