+				coverage_add_include(E->next()->get());
+			} else if (arg == "--coverage-exclude" && E->next()) {
+				coverage_add_exclude(E->next()->get());
+			}
+		}
+		if (!coverage_output_path.is_empty()) {
+			coverage_start();
+		}
